iv><label class="form-check"><input class="form-check-input" type="checkbox" name="wallet_auto_require_account_name" value="1" <?=$withdrawalPolicy['require_account_name']?'checked':''?>> Require verified account name</label><button class="btn btn-success">Save Withdrawal Rules</button></form></div></div></div><div class="col-lg-5"><div class="card"><div class="card-body"><h2 class="h5">Current Enforcement</h2><p>Automation: <strong><?=$withdrawalPolicy['auto_enabled']?'Enabled':'Disabled'?></strong></p><p>First withdrawal SLA: <strong><?=e((string)$withdrawalPolicy['first_withdrawal_review_hours'])?>h</strong></p><p>Auto eligible pending: <strong><?=number_format($autoPending)?></strong></p><p>Manual reviews due in 24h: <strong><?=number_format($firstReviewDue)?></strong></p></div></div></div></div><?php endif?>
